<?php
namespace App\Services\Reports;
use App\Support\Legacy as L;
use App\Services\InventoryService;
use App\Http\Controllers\WorkspaceController;
use Illuminate\Support\Facades\DB;
use Illuminate\Http\Request;
use Carbon\Carbon;
class ReportData {
 public const LIMIT=10000;
 public function __construct(private InventoryService $inventory,private ReportRegistry $registry){}
 private function scope($q,string $field,array $f){
  $u=auth()->user();if($u->role!=='admin')$q->whereIn($field,json_decode($u->warehouses??'[]',true)??[]);
  if(!empty($f['warehouse'])){$this->inventory->authorize((int)$f['warehouse']);$q->where($field,(int)$f['warehouse']);}return $q;
 }
 private function classification($q,array $f){foreach(['family'=>'fa.famitm_id','group'=>'g.gruitm_id','category'=>'ca.catitm_id','product'=>'c.cataitm_id'] as $k=>$field)if(!empty($f[$k]))$q->where($field,$f[$k]);return $q;}
 private function joins($q,string $product,string $warehouse){return $q->join('msib.catalogoitem as c','c.cataitm_id','=',$product)->join('msib.almacen as a','a.alm_id','=',$warehouse)->join('msib.categoriaitem as ca','ca.catitm_id','=','c.catitm_id')->join('msib.grupoitem as g','g.gruitm_id','=','ca.gruitm_id')->leftJoin('msib.familiaitem as fa','fa.famitm_id','=','g.famitm_id')->join('msib.oficinas as o','o.ofi_id','=','a.ofi_id');}
 public function base(string $title,string $code,string $source,array $f=[]):array {
  return ['title'=>$title,'code'=>$code,'sources'=>[$source],'filters'=>$f,'metadata'=>[],'sections'=>[],'signatures'=>[],'notes'=>[],'watermark'=>null,'orientation'=>'landscape','emitted_at'=>now()->format('d/m/Y H:i:s'),'actor'=>auth()->user()->username,'row_count'=>0];
 }
 public function section(string $title,array $columns,array $rows,array $totals=[]):array {if(count($rows)>self::LIMIT)InventoryService::fail('El reporte supera 10.000 filas. Acote los filtros; no se recortan datos silenciosamente.');return compact('title','columns','rows','totals');}
 public function cols(array $labels,array $numbers=[],array $money=[]):array {return array_map(fn($k)=>['key'=>$k,'label'=>$labels[$k],'type'=>in_array($k,$money)?'money':(in_array($k,$numbers)?'number':(in_array($k,['fecha','vencimiento'])?'date':'text'))],array_keys($labels));}
 private function finish(array $r):array {$r['row_count']=array_sum(array_map(fn($s)=>count($s['rows']),$r['sections']));if($r['row_count']>self::LIMIT)InventoryService::fail('Acote los filtros: el reporte supera 10.000 filas.');return $r;}
 private function state(int $s):string {return [5000=>'BORRADOR',5001=>'ELABORADO',5002=>'APROBADO',5003=>'RECHAZADO',5004=>'ANULADO'][$s]??(L::table('tablabasedata')->where('tabbasdat_id',$s)->value('tabbasdat_descripcion')??(string)$s);}
 public function document(string $kind,string $id):array {
  $d=$this->inventory->document($kind,$id);$in=$kind==='ingresos';$p=$in?'ingalm':'salalm';$adjust=$kind==='ajustes';$r=$this->base($in?'Documento de ingreso a almacén':($adjust?'Documento de ajuste de almacén':($kind==='transferencias'?'Documento de salida por transferencia':'Documento de salida de almacén')),$in?'IT-A-0001':($adjust?'IT-A-0004':'IT-A-0002'),$in?'Almacenes.Reporte_001':($adjust?'Almacenes.Reporte_004':'Almacenes.Reporte_002'));$r['reference']=$id;$r['orientation']='landscape';
  $warehouse=L::table('almacen as a')->join('msib.oficinas as o','o.ofi_id','=','a.ofi_id')->where('a.alm_id',$d->{$p.'alm_id'})->first();
  $counterparty=$d->{$p.'_tipo_proveedor'}==='PROVEEDOR'?L::table('proveedor')->where('prv_id',$d->{$p.'prv_id'})->value('prv_nombre'):L::table('asignacionpersonal')->where('asgper_id',$d->{$p.'asgper_id'})->value('asgper_asignacion_fill');
  $r['metadata']=['Nro. documento'=>trim($d->{$p.'_nro_documento'})?:'Sin numerar','Fecha de almacén'=>$d->{$p.'_fecha_almacen'},'Estado'=>$this->state($d->{$p.'_estado_id'}),'Oficina'=>$warehouse->ofi_nombre,'Almacén'=>$warehouse->alm_nombre,'Tipo'=>L::table('tipodocumento')->where('tipdoc_id',$d->{$p.'tipdoc_id'})->value('tipdoc_nombre'),$in?'Recibido de':'Entregado a'=>$counterparty?:'Sin especificar','Financiamiento'=>L::table('tablabasedata')->where('tabbasdat_id',$d->{$p.'fuefin_id'})->value('tabbasdat_descripcion')];
  if(($in&&(int)$d->ingalmtipdoc_id===1000)||(!$in&&(int)$d->salalmtipdoc_id===2000)){$other=$in?$d->ingalmalmori_id:$d->salalmalmdes_id;$r['metadata'][$in?'Almacén de origen':'Almacén de destino']=L::table('almacen')->where('alm_id',$other)->value('alm_nombre')??(string)$other;}
  $state=(int)$d->{$p.'_estado_id'};if($state!==5002)$r['watermark']=$state===5001?'ELABORADO - NO APROBADO':$this->state($state);
  $items=L::table(($in?'ingresoalmacenitem':'salidaalmacenitem').' as l')->join('msib.catalogoitem as c','c.cataitm_id','=','l.cataitm_id')->join('msib.categoriaitem as ca','ca.catitm_id','=','c.catitm_id')->leftJoin('msib.tablabasedata as u','u.tabbasdat_id','=','c.cataitmunimed_id')->leftJoin('msib.tablabasedata as f','f.tabbasdat_id','=','l.'.$p.'itmfuefin_id')->where('l.'.$p.'_id',$id)->orderBy('l.'.$p.'itm_id')->select(['l.*','c.cataitm_nombre','ca.catitm_nombre','u.tabbasdat_descripcion as unidad','f.tabbasdat_descripcion as financiamiento'])->get();
  $rows=[];$total=0;foreach($items as $l){$qty=$in?$l->ingalmitm_cantidad_ingreso+$l->ingalmitm_cantidad_ingreso_ajuste:($adjust?$l->salalmitm_cantidad_ajuste:$l->salalmitm_cantidad_salida);$cost=(float)$l->{$p.'itm_costo_unitario'};$amount=round(($in?$qty:($l->salalmitm_cantidad_salida+$l->salalmitm_cantidad_ajuste))*$cost,2);$total+=$amount;$rows[]=['nro'=>$l->{$p.'itm_id'},'codigo'=>$l->cataitm_id,'producto'=>$l->cataitm_nombre,'categoria'=>$l->catitm_nombre,'unidad'=>$l->unidad,'cantidad'=>$qty,'costo'=>$cost,'lote'=>$l->{$p.'itm_lote'},'vencimiento'=>$this->date($l->{$p.'itm_fecha_exp'}),'financiamiento'=>$l->financiamiento,'subtotal'=>$amount];}
  $r['sections'][]=$this->section('Detalle de productos',$this->cols(['nro'=>'Nro.','codigo'=>'Código','producto'=>'Producto / insumo','categoria'=>'Categoría','unidad'=>'U.M.','cantidad'=>$adjust?'Ajuste (+/-)':'Cantidad','costo'=>'Costo neto (Bs)','lote'=>'Lote','vencimiento'=>'Vencimiento','financiamiento'=>'F. financ.','subtotal'=>'Subtotal (Bs)'],['nro','cantidad'],['costo','subtotal']),$rows,['subtotal'=>round($total,2)]);
  $r['notes'][]=trim($d->{$in?'ingalm_nota':'salalmnota'})?:'Sin notas ni observaciones.';$r['signatures']=$this->signatures($id);
  $r['notes'][]='Los nombres de elaboración/aprobación son registros del sistema. Los espacios de firma se completan al suscribir el documento; no constituyen una firma digital.';
  return $this->finish($r);
 }
 private function signatures(string $id):array {
  $out=[];foreach([5001=>'Elaborado por',5002=>'Aprobado por'] as $state=>$statement){$n=DB::table('app_document_signatures')->where('document_id',$id)->where('state',$state)->first();$old=L::table('flujoaprobaciondocumento')->where('fluaprdoc_referencia_id',$id)->where('fluaprdoc_estado_documento_id',$state)->orderByDesc('fluaprdoc_fecha_aprobacion')->orderByDesc('fluaprdoc_fecha_audit')->first();
   if($n)$out[]=['statement'=>$n->statement,'name'=>$n->name,'role'=>$n->role,'date'=>$n->signed_at,'origin'=>'Registro de la nueva aplicación'];
   elseif($old)$out[]=['statement'=>$old->fluaprdoc_tenor?:$statement,'name'=>$old->fluaprdoc_personal_nombres_fill,'role'=>$old->fluaprdoc_cargo_nombre,'date'=>$old->fluaprdoc_fecha_aprobacion,'origin'=>'Flujo original'];
   else $out[]=['statement'=>$statement,'name'=>'','role'=>'','date'=>'','origin'=>'Sin firma registrada'];
  }return $out;
 }
 public function date(?string $date):string {return !$date||$date==='0001-01-01'?'':$date;}
 public function build(string $id,array $f):array {
  $def=$this->registry->get($id);$r=$this->base($def['title'],$def['code'],$def['source'],$f);
  if($id==='kardex-valorado')$r=$this->kardex($r,$f);
  elseif(in_array($id,['saldo-mensual','movimientos-periodo','vencimientos-mensual']))$r=$this->monthlyReport($r,$id,$f);
  elseif(in_array($id,['inventario-blanco','inventario-resultados']))$r=$this->physical($r,$f,$id==='inventario-blanco');
  elseif($id==='resumen-costos')$r=$this->costSummary($r,$f);
  elseif(str_starts_with($id,'listado-'))$r=$this->listing($r,substr($id,8),$f);
  else abort(404);return $this->finish($r);
 }
 private function listing(array $r,string $module,array $f):array {
  $request=new Request($f);$request->attributes->set('report_export',true);$data=app(WorkspaceController::class)->records($request,$module);$rows=array_map(fn($x)=>(array)$x,$data['data']);$keys=$rows?array_keys($rows[0]):($data['editable']??[]);$labels=json_decode(file_get_contents(resource_path('js/labels.json')),true);$cols=[];
  foreach($keys as $k){if(in_array($k,['lines','detail']))continue;$cols[]=['key'=>$k,'label'=>$labels[$k]??str_replace('_',' ',$k),'type'=>preg_match('/costo|valor|precio/',$k)?'money':(preg_match('/cantidad|saldo|^ingreso$|^salida$|^ajuste$/',$k)?'number':'text')];}
  foreach($rows as &$row)if(isset($row['estado'])&&is_numeric($row['estado']))$row['estado']=$this->state((int)$row['estado']);unset($row);
  $r['sections'][]=$this->section('Listado completo según filtros',$cols,$rows);$r['metadata']=['Alcance'=>'Permisos del usuario autenticado','Registros'=>count($rows)];return $r;
 }
 private function snapshot(int $year,int $month,array $f):array {
  $q=$this->joins(L::table('kardexconsolidadomensual as k'),'k.cataitm_id','k.almcataitmalm_id')->leftJoin('msib.tablabasedata as ff','ff.tabbasdat_id','=','k.almitmdisfuefin_id')->where('k.karconmes_anio',$year)->where('k.karconmes_mes',$month);
  $this->scope($q,'k.almcataitmalm_id',$f);$this->classification($q,$f);if(!empty($f['funding']))$q->where('k.almitmdisfuefin_id',$f['funding']);if(!empty($f['channel']))$q->where('o.ofican_id',$f['channel']);
  $raw=$q->orderBy('c.cataitm_id')->orderBy('k.almcataitmalm_id')->orderBy('k.karconmes_lote')->limit(self::LIMIT+1)->get(['k.*','c.cataitm_nombre','fa.famitm_nombre','g.gruitm_nombre','ca.catitm_nombre','a.alm_nombre','ff.tabbasdat_descripcion as fuente']);if($raw->count()>self::LIMIT)InventoryService::fail('Acote los filtros del consolidado.');
  $rows=[];foreach($raw as $x){$row=['periodo'=>sprintf('%04d-%02d',$year,$month),'almacen'=>$x->alm_nombre,'warehouse_id'=>$x->almcataitmalm_id,'codigo'=>$x->cataitm_id,'familia'=>$x->famitm_nombre,'grupo'=>$x->gruitm_nombre,'categoria'=>$x->catitm_nombre,'producto'=>$x->cataitm_nombre,'financiamiento'=>$x->fuente,'funding_id'=>$x->almitmdisfuefin_id,'lote'=>$x->karconmes_lote,'vencimiento'=>$this->date($x->karconmes_fecha_exp),'costo_unitario'=>(float)$x->karconmes_costo_unitario];foreach(['anterior'=>'saldo_anterior','ingreso'=>'ingreso','salida'=>'salida','ajuste'=>'ajuste','traspaso'=>'traspasos'] as $suffix=>$field)$row['cantidad_'.$suffix]=(int)$x->{'karconmes_cantidad_'.$field};foreach(['anterior'=>'saldo_anterior','ingreso'=>'ingreso','salida'=>'salida','ajuste'=>'ajuste','traspaso'=>'traspaso'] as $suffix=>$field)$row['costo_'.$suffix]=(float)$x->{'karconmes_costo_'.$field};$rows[]=$this->balances($row);}
  return $rows;
 }
 private function balances(array $x):array {$x['cantidad_saldo']=$x['cantidad_anterior']+$x['cantidad_ingreso']-$x['cantidad_salida']+$x['cantidad_ajuste']+$x['cantidad_traspaso'];$x['costo_saldo']=round($x['costo_anterior']+$x['costo_ingreso']-$x['costo_salida']+$x['costo_ajuste']+$x['costo_traspaso'],2);return $x;}
 private function lotKey(array $x):string {return json_encode([$x['warehouse_id'],$x['codigo'],$x['funding_id'],$x['lote'],$x['vencimiento'],number_format($x['costo_unitario'],2,'.','')]);}
 public function monthly(int $year,int $month,array $f,?array $carry=null):array {
  if(($f['basis']??'auto')==='snapshot')return $this->snapshot($year,$month,$f);
  $d=Carbon::create($year,$month,1);$previous=$d->copy()->subMonth();
  if($carry===null){$changedIds=DB::table('app_audit')->whereIn('action',['approve','cancel','receive'])->select('reference');$iq=L::table('ingresoalmacen')->where(function($q)use($changedIds){$q->whereIn('ingalm_id',$changedIds)->orWhereIn('ingalm_ref_transferencia_salalm_id',$changedIds);})->where('ingalm_fecha_almacen','<',$d->toDateString());$sq=L::table('salidaalmacen')->whereIn('salalm_id',$changedIds)->where('salalm_fecha_almacen','<',$d->toDateString());$this->scope($iq,'ingalmalm_id',$f);$this->scope($sq,'salalmalm_id',$f);$dates=array_filter([$iq->min('ingalm_fecha_almacen'),$sq->min('salalm_fecha_almacen')]);if($dates){$anchor=Carbon::parse(min($dates))->startOfMonth();if($anchor->diffInMonths($d)>60)InventoryService::fail('El cálculo en vivo requiere más de 60 meses; revise y consolide los períodos afectados.');for($m=$anchor->copy();$m->lt($d);$m->addMonth())$carry=$this->monthly($m->year,$m->month,$f,$carry??$this->snapshot($m->copy()->subMonth()->year,$m->copy()->subMonth()->month,$f));}}
  $rows=[];foreach($carry??$this->snapshot($previous->year,$previous->month,$f) as $x){$x['cantidad_anterior']=$x['cantidad_saldo'];$x['costo_anterior']=$x['costo_saldo'];$x['periodo']=$d->format('Y-m');foreach(['ingreso','salida','ajuste','traspaso'] as $k){$x['cantidad_'.$k]=0;$x['costo_'.$k]=0;}$key=$this->lotKey($x);if(isset($rows[$key])){$rows[$key]['cantidad_anterior']+=$x['cantidad_anterior'];$rows[$key]['costo_anterior']+=$x['costo_anterior'];}else $rows[$key]=$x;}
  foreach([true,false] as $in){$p=$in?'ingalm':'salalm';$q=$this->joins(L::table(($in?'ingresoalmacenitem':'salidaalmacenitem').' as l')->join('msib.'.($in?'ingresoalmacen':'salidaalmacen').' as h','h.'.$p.'_id','=','l.'.$p.'_id'),'l.cataitm_id','l.almcataitmalm_id')->leftJoin('msib.tablabasedata as ff','ff.tabbasdat_id','=','l.'.$p.'itmfuefin_id')->where('h.'.$p.'_estado_id',5002)->whereBetween('h.'.$p.'_fecha_almacen',[$d->toDateString(),$d->copy()->endOfMonth()->toDateString()]);$this->scope($q,'l.almcataitmalm_id',$f);$this->classification($q,$f);if(!empty($f['funding']))$q->where('l.'.$p.'itmfuefin_id',$f['funding']);if(!empty($f['channel']))$q->where('o.ofican_id',$f['channel']);
   $raw=$q->limit(self::LIMIT+1)->get(['l.*','h.'.$p.'tipdoc_id as tipo','a.alm_nombre','c.cataitm_nombre','fa.famitm_nombre','g.gruitm_nombre','ca.catitm_nombre','ff.tabbasdat_descripcion as fuente']);if($raw->count()>self::LIMIT)InventoryService::fail('Acote los filtros: demasiados movimientos para el cálculo.');
   foreach($raw as $l){$x=['periodo'=>$d->format('Y-m'),'almacen'=>$l->alm_nombre,'warehouse_id'=>$l->almcataitmalm_id,'codigo'=>$l->cataitm_id,'familia'=>$l->famitm_nombre,'grupo'=>$l->gruitm_nombre,'categoria'=>$l->catitm_nombre,'producto'=>$l->cataitm_nombre,'financiamiento'=>$l->fuente,'funding_id'=>$l->{$p.'itmfuefin_id'},'lote'=>$l->{$p.'itm_lote'}??'','vencimiento'=>$this->date($l->{$p.'itm_fecha_exp'}),'costo_unitario'=>(float)$l->{$p.'itm_costo_unitario'}];$key=$this->lotKey($x);if(!isset($rows[$key])){foreach(['anterior','ingreso','salida','ajuste','traspaso'] as $k){$x['cantidad_'.$k]=0;$x['costo_'.$k]=0;}$rows[$key]=$x;}$x=&$rows[$key];$cost=(float)$l->{$p.'itm_costo_unitario'};
    if($in){$qty=$l->ingalmitm_cantidad_ingreso;$kind=(int)$l->tipo===1000?'traspaso':((int)$l->tipo===9?'ajuste':'ingreso');$x['cantidad_'.$kind]+=$qty;$x['costo_'.$kind]+=$qty*$cost;$x['cantidad_ajuste']+=$l->ingalmitm_cantidad_ingreso_ajuste;$x['costo_ajuste']+=$l->ingalmitm_cantidad_ingreso_ajuste*$cost;}
    else{$kind=(int)$l->tipo===2000?'traspaso':'salida';$sign=$kind==='traspaso'?-1:1;$x['cantidad_'.$kind]+=$sign*$l->salalmitm_cantidad_salida;$x['costo_'.$kind]+=$sign*$l->salalmitm_cantidad_salida*$cost;$x['cantidad_ajuste']+=$l->salalmitm_cantidad_ajuste;$x['costo_ajuste']+=$l->salalmitm_cantidad_ajuste*$cost;}unset($x);
   }
  }$out=array_map(fn($x)=>$this->balances($x),array_values($rows));usort($out,fn($a,$b)=>[$a['codigo'],$a['warehouse_id'],$a['lote']]<=>[$b['codigo'],$b['warehouse_id'],$b['lote']]);return $out;
 }
 private function monthlyCols():array {return $this->cols(['periodo'=>'Período','almacen'=>'Almacén','codigo'=>'Cod. ítem','familia'=>'Familia','grupo'=>'Grupo','categoria'=>'Categoría','producto'=>'Producto / insumo','financiamiento'=>'F. financ.','lote'=>'Lote','vencimiento'=>'Vencimiento','costo_unitario'=>'Precio unit. (Bs)','cantidad_anterior'=>'Cant. saldo ant.','cantidad_ingreso'=>'Cant. ingreso','cantidad_salida'=>'Cant. salida','cantidad_ajuste'=>'Cant. ajuste (+/-)','cantidad_traspaso'=>'Cant. traspaso','cantidad_saldo'=>'Cant. saldo','costo_anterior'=>'Costo saldo ant.','costo_ingreso'=>'Costo ingreso','costo_salida'=>'Costo salida','costo_ajuste'=>'Costo ajuste (+/-)','costo_traspaso'=>'Costo traspaso','costo_saldo'=>'Costo saldo'],['cantidad_anterior','cantidad_ingreso','cantidad_salida','cantidad_ajuste','cantidad_traspaso','cantidad_saldo'],['costo_unitario','costo_anterior','costo_ingreso','costo_salida','costo_ajuste','costo_traspaso','costo_saldo']);}
 private function monthlyReport(array $r,string $id,array $f):array {
  $r['notes'][]=($f['basis']??'auto')==='snapshot'?'Fuente: consolidado almacenado del sistema original. No se recalcula.':'Fuente: saldo consolidado del mes anterior más documentos aprobados del mes consultado. Los traspasos se separan del consumo. No modifica la base.';
  if($id==='movimientos-periodo'){
   $start=Carbon::parse($f['from'])->startOfMonth();$end=Carbon::parse($f['to'])->startOfMonth();$previous=null;$all=[];for($date=$start->copy();$date->lte($end);$date->addMonth()){
    $current=$this->monthly($date->year,$date->month,$f);$groups=[];foreach($current as $row){$key=$row['warehouse_id'].':'.$row['codigo'];if(!isset($groups[$key])){$groups[$key]=$row;foreach(['anterior','ingreso','salida','ajuste','traspaso','saldo'] as $k){$groups[$key]['cantidad_'.$k]=0;$groups[$key]['costo_'.$k]=0;}$groups[$key]['lote']='(TODOS)';$groups[$key]['financiamiento']=empty($f['funding'])?'(TODOS)':$row['financiamiento'];$groups[$key]['vencimiento']='';$groups[$key]['costo_unitario']=null;}foreach(['anterior','ingreso','salida','ajuste','traspaso','saldo'] as $k){$groups[$key]['cantidad_'.$k]+=$row['cantidad_'.$k];$groups[$key]['costo_'.$k]+=$row['costo_'.$k];}}
    foreach($groups as &$row)if(!$date->equalTo($start)){$row['cantidad_anterior']=0;$row['costo_anterior']=0;}unset($row);$all=array_merge($all,array_values($groups));
   }$r['metadata']=['Desde (mes)'=>$start->format('Y-m'),'Hasta (mes)'=>$end->format('Y-m'),'Agrupación'=>'Producto / almacén / mes'];$r['notes'][]='Replica el informe Excel por meses completos. El saldo anterior se muestra una sola vez, en el primer mes, sin sumar saldos finales entre meses.';$r['sections'][]=$this->section('Movimientos por período',$this->monthlyCols(),$all);return $r;
  }
  $year=(int)$f['year'];$month=(int)$f['month'];$rows=$this->monthly($year,$month,$f);$r['metadata']=['Período'=>sprintf('%04d-%02d',$year,$month),'Base'=>($f['basis']??'auto')==='snapshot'?'Consolidado almacenado':'Documentos aprobados + saldo anterior'];
  if($id==='vencimientos-mensual'){
   $ranges=L::table('rangodiaexpiracion')->when(!empty($f['range']),fn($q)=>$q->where('ranexp_id',$f['range']))->orderBy('ranexp_valor_dia')->get();if($ranges->isEmpty())InventoryService::fail('No hay rangos de vencimiento configurados.');
   foreach($ranges as $range){$limit=today()->addDays($range->ranexp_valor_dia)->toDateString();$filtered=[];foreach($rows as $row)if($row['cantidad_saldo']>0&&$row['vencimiento']&&$row['vencimiento']<=$limit){$days=(int)today()->diffInDays(Carbon::parse($row['vencimiento']),false);$row['dias']=$days<0?'EXPIRADO':$days.' día(s)';$filtered[]=$row;}$r['sections'][]=$this->section($range->ranexp_descripcion.' (hasta '.$limit.')',$this->cols(['codigo'=>'Código','producto'=>'Producto','almacen'=>'Almacén','lote'=>'Lote','vencimiento'=>'Vencimiento','financiamiento'=>'F. financ.','cantidad_saldo'=>'Saldo','dias'=>'Días faltantes'],['cantidad_saldo']),$filtered);}
   $r['notes'][]='Los rangos del XPZ son acumulativos: un mismo lote puede aparecer en más de un rango. El vencimiento se compara con la fecha de emisión, no con el mes histórico.';return $r;
  }
  $r['sections'][]=$this->section('Detalle por producto y lote',$this->monthlyCols(),$rows);$group=[];foreach($rows as $x){$key=$x['codigo'];if(!isset($group[$key])){$group[$key]=['codigo'=>$key,'producto'=>$x['producto']];foreach(['anterior','ingreso','salida','ajuste','traspaso','saldo'] as $k){$group[$key]['cantidad_'.$k]=0;$group[$key]['costo_'.$k]=0;}}foreach(['anterior','ingreso','salida','ajuste','traspaso','saldo'] as $k){$group[$key]['cantidad_'.$k]+=$x['cantidad_'.$k];$group[$key]['costo_'.$k]+=$x['costo_'.$k];}}
  $subtotalCols=array_values(array_filter($this->monthlyCols(),fn($c)=>in_array($c['key'],['codigo','producto'])||str_starts_with($c['key'],'cantidad_')||str_starts_with($c['key'],'costo_')&&$c['key']!=='costo_unitario'));$r['sections'][]=$this->section('Totales por producto',$subtotalCols,array_values($group));return $r;
 }

 private function kardex(array $r,array $f):array {
  $w=(int)$f['warehouse'];$this->inventory->authorize($w);$product=L::table('catalogoitem as c')->join('msib.categoriaitem as ca','ca.catitm_id','=','c.catitm_id')->leftJoin('msib.tablabasedata as u','u.tabbasdat_id','=','c.cataitmunimed_id')->where('c.cataitm_id',$f['product'])->first(['c.*','ca.catitm_nombre','u.tabbasdat_descripcion as unidad']);if(!$product)abort(404);
  $start=Carbon::parse($f['from']);$before=$start->copy()->startOfMonth()->subDay();$baseline=$this->monthly($before->year,$before->month,['warehouse'=>$w,'product'=>$f['product'],'funding'=>$f['funding']??null]);$quantity=array_sum(array_column($baseline,'cantidad_saldo'));$cost=array_sum(array_column($baseline,'costo_saldo'));
  $q=L::table('kardexmovimientoitem as k')->leftJoin('msib.tablabasedata as ff','ff.tabbasdat_id','=','k.karmovitm_fuefin_id')->where('k.almcataitmalm_id',$w)->where('k.cataitm_id',$f['product']);if(!empty($f['funding']))$q->where('k.karmovitm_fuefin_id',$f['funding']);
  $earlier=(clone $q)->whereBetween('k.karmovitm_fecha',[$start->copy()->startOfMonth()->toDateString(),$start->copy()->subDay()->toDateString()])->selectRaw('COALESCE(sum(karmovitm_cantidad_ingreso-karmovitm_cantidad_salida+karmovitm_cantidad_ajuste),0) as quantity,COALESCE(sum(karmovitm_costo_ingreso-karmovitm_costo_salida+karmovitm_costo_ajuste),0) as cost')->first();$quantity+=(int)$earlier->quantity;$cost+=(float)$earlier->cost;
  $openingQ=$quantity;$openingCost=$cost;$r['metadata']=['Producto'=>$product->cataitm_nombre,'Código'=>$product->cataitm_id,'Categoría'=>$product->catitm_nombre,'Unidad'=>$product->unidad,'Almacén'=>L::table('almacen')->where('alm_id',$w)->value('alm_nombre'),'Desde'=>$f['from'],'Hasta'=>$f['to'],'Cantidad anterior'=>$quantity,'Costo anterior (Bs)'=>number_format($cost,2,'.','')];
  $moves=$q->whereBetween('k.karmovitm_fecha',[$f['from'],$f['to']])->orderBy('k.karmovitm_fecha')->orderBy('k.karmovitm_nro_orden')->orderBy('k.karmovitm_id')->orderBy('k.karmovitm_detalle_id')->limit(self::LIMIT+1)->get(['k.*','ff.tabbasdat_descripcion as fuente']);if($moves->count()>self::LIMIT)InventoryService::fail('Acote el período del kardex.');$rows=[];
  foreach($moves as $m){$quantity+=$m->karmovitm_cantidad_ingreso-$m->karmovitm_cantidad_salida+$m->karmovitm_cantidad_ajuste;$cost+=(float)$m->karmovitm_costo_ingreso-(float)$m->karmovitm_costo_salida+(float)$m->karmovitm_costo_ajuste;$rows[]=['fecha'=>$m->karmovitm_fecha,'documento'=>$m->karmovitm_nro_documento,'detalle'=>$m->karmovitm_glosa,'tipo'=>$m->karmovitm_tipo,'lote'=>$m->karmovitm_lote,'vencimiento'=>$this->date($m->karmovitm_fecha_exp),'financiamiento'=>$m->fuente,'ingreso'=>$m->karmovitm_cantidad_ingreso,'salida'=>$m->karmovitm_cantidad_salida,'ajuste'=>$m->karmovitm_cantidad_ajuste,'saldo'=>$quantity,'costo_ingreso'=>(float)$m->karmovitm_costo_ingreso,'costo_salida'=>(float)$m->karmovitm_costo_salida,'costo_ajuste'=>(float)$m->karmovitm_costo_ajuste,'costo_saldo'=>round($cost,2)];}
  $r['sections'][]=$this->section('Movimientos aprobados',$this->cols(['fecha'=>'Fecha','documento'=>'Nro. documento','detalle'=>'Detalle del movimiento','tipo'=>'Tipo','lote'=>'Lote','vencimiento'=>'Vencimiento','financiamiento'=>'F. financ.','ingreso'=>'Ingreso','salida'=>'Salida','ajuste'=>'Ajuste (+/-)','saldo'=>'Saldo','costo_ingreso'=>'Costo ingreso','costo_salida'=>'Costo salida','costo_ajuste'=>'Costo ajuste','costo_saldo'=>'Costo saldo'],['ingreso','salida','ajuste','saldo'],['costo_ingreso','costo_salida','costo_ajuste','costo_saldo']),$rows,['saldo'=>$quantity,'costo_saldo'=>round($cost,2)]);
  $r['notes'][]='Saldo anterior del consolidado del mes previo, más movimientos aprobados anteriores al inicio dentro del mes. El filtro de financiamiento también se aplica al saldo inicial.';return $r;
 }
 private function physical(array $r,array $f,bool $blank):array {
  $id=$f['count_id'];$source=$f['count_source']??'legacy';$rows=[];$r['reference']=$id;
  if($source==='legacy'){
   $h=L::table('inventariofisico')->where('invfis_id',$id)->first();if(!$h)abort(404);$this->inventory->authorize((int)$h->invfisalm_id);$w=$h->invfisalm_id;
   $r['metadata']=['Nro. documento'=>$h->invfis_nro_documento,'Fecha de inicio'=>$h->invfis_fecha,'Fecha de conclusión'=>$this->date($h->invfis_fecha_conclusion),'Estado'=>$this->state($h->invfis_estado),'Responsable'=>$h->invfis_nombre_encargado];$r['notes'][]=$h->invfis_notas;
   $data=L::table('inventariofisicoitems as l')->join('msib.catalogoitem as c','c.cataitm_id','=','l.cataitm_id')->leftJoin('msib.tablabasedata as ff','ff.tabbasdat_id','=','l.almitmdisfuefin_id')->where('l.invfis_id',$id)->orderBy('l.cataitm_id')->orderBy('l.invfisitm_id')->get(['l.*','c.cataitm_nombre','ff.tabbasdat_descripcion as fuente']);
   foreach($data as $l)$rows[]=['codigo'=>$l->cataitm_id,'producto'=>$l->cataitm_nombre,'lote'=>$l->invfisitm_lote,'vencimiento'=>$this->date($l->invfisitm_fecha_exp),'financiamiento'=>$l->fuente,'costo'=>(float)$l->invfisitm_costo_unitario,'saldo'=>$l->invfisitm_cantidad_actual,'recuento'=>$blank?'':$l->invfisitm_cantidad_fisico,'diferencia'=>$blank?'':$l->invfisitm_cantidad_fisico-$l->invfisitm_cantidad_actual,'observaciones'=>$blank?'':$l->invfisitm_observacion];
  }else{
   $h=DB::table('app_count_sessions')->where('id',$id)->first();if(!$h)abort(404);$w=$h->warehouse_id;$this->inventory->authorize((int)$w);$r['metadata']=['Nro. documento'=>$id,'Fecha de inicio'=>$h->date,'Estado'=>$h->status,'Responsable'=>$h->actor];$r['notes'][]=$h->notes;
   foreach(json_decode($h->lines,true) as $l){$lot=L::table('ingresoalmacenitem')->where('ingalm_id',$l['receipt_id'])->where('ingalmitm_id',$l['receipt_line_id'])->first();$rows[]=['codigo'=>$l['product_id'],'producto'=>$l['producto'],'lote'=>$lot?->ingalmitm_lote,'vencimiento'=>$this->date($lot?->ingalmitm_fecha_exp),'financiamiento'=>L::table('tablabasedata')->where('tabbasdat_id',$l['funding_id'])->value('tabbasdat_descripcion'),'costo'=>(float)($lot?->ingalmitm_costo_unitario??0),'saldo'=>$l['system'],'recuento'=>$blank?'':$l['count'],'diferencia'=>$blank?'':$l['difference'],'observaciones'=>''];}
  }
  $r['metadata']['Almacén']=L::table('almacen')->where('alm_id',$w)->value('alm_nombre');$r['sections'][]=$this->section('Conteo físico',$this->cols(['codigo'=>'Código','producto'=>'Producto / insumo','lote'=>'Lote','vencimiento'=>'Vencimiento','financiamiento'=>'F. financ.','costo'=>'Costo unit. (Bs)','saldo'=>'Saldo sistema','recuento'=>'Recuento físico','diferencia'=>'Diferencia','observaciones'=>'Observaciones'],['saldo','recuento','diferencia'],['costo']),$rows);$r['signatures']=[['statement'=>'Responsable del inventario','name'=>$r['metadata']['Responsable'],'role'=>'','date'=>'','origin'=>'Campo del inventario'],['statement'=>'Revisado por','name'=>'','role'=>'','date'=>'','origin'=>'Sin firma registrada']];if($blank)$r['notes'][]='Formato de trabajo: recuento, diferencia y observaciones se dejan en blanco para completar durante el conteo.';return $r;
 }
 private function costSummary(array $r,array $f):array {
  $q=$this->joins(L::table('resumencostoinventario as k'),'k.cataitm_id','k.almcataitmalm_id')->leftJoin('msib.tablabasedata as ff','ff.tabbasdat_id','=','k.almitmdisfuefin_id')->leftJoin('msib.centrocosto as cc','cc.ccos_id','=','o.ccos_id')->whereBetween('k.rescosinv_fecha',[$f['from'],$f['to']]);$this->scope($q,'k.almcataitmalm_id',$f);$this->classification($q,$f);if(!empty($f['funding']))$q->where('k.almitmdisfuefin_id',$f['funding']);if(!empty($f['cost_group']))$q->where('cc.ccosgru_id',$f['cost_group']);
  $data=$q->orderBy('k.rescosinv_fecha')->orderBy('k.cataitm_id')->limit(self::LIMIT+1)->get(['k.*','c.cataitm_nombre','a.alm_nombre','o.ofi_nombre','ff.tabbasdat_descripcion as fuente']);$rows=[];foreach($data as $l){$row=['fecha'=>$l->rescosinv_fecha,'almacen'=>$l->alm_nombre,'oficina'=>$l->ofi_nombre,'codigo'=>$l->cataitm_id,'producto'=>$l->cataitm_nombre,'financiamiento'=>$l->fuente];foreach(['anterior'=>'saldo_anterior','ingresos'=>'ingresos','salidas'=>'salidas','ajustes'=>'ajustes','traspasos'=>'traspasos'] as $key=>$suffix)$row['costo_'.$key]=(float)$l->{'rescosinv_costo_'.$suffix};$row['costo_saldo']=round(array_sum(array_intersect_key($row,array_flip(['costo_anterior','costo_ingresos','costo_salidas','costo_ajustes','costo_traspasos']))),2);$rows[]=$row;}
  $r['sections'][]=$this->section('Resumen almacenado de costos',$this->cols(['fecha'=>'Fecha','almacen'=>'Almacén','oficina'=>'Oficina','codigo'=>'Código','producto'=>'Producto','financiamiento'=>'F. financ.','costo_anterior'=>'Costo anterior','costo_ingresos'=>'Ingresos','costo_salidas'=>'Salidas (signo original)','costo_ajustes'=>'Ajustes','costo_traspasos'=>'Traspasos','costo_saldo'=>'Saldo'],[],['costo_anterior','costo_ingresos','costo_salidas','costo_ajustes','costo_traspasos','costo_saldo']),$rows);
  $r['notes'][]='Resumen histórico almacenado. Respeta la fórmula del XPZ: costo anterior + ingresos + salidas + ajustes + traspasos; conserva el signo de las salidas guardadas. Los saldos de fechas distintas no se suman como un saldo final único.';return $r;
 }
 public function asset(string $id):array {
  $h=L::table('activofijo as a')->where('a.actfij_id',$id);$u=auth()->user();if($u->role!=='admin')$h->whereIn('a.ofi_id',L::table('almacen')->whereIn('alm_id',json_decode($u->warehouses??'[]',true))->pluck('ofi_id'));$a=$h->first();if(!$a)abort(404);
  $r=$this->base('Ficha de activo fijo y constancia de custodia','AF-FICHA','Activos.ActivoFijoWWExportReport / constancia adaptada');$r['reference']=$id;$r['orientation']='portrait';$r['metadata']=['Código'=>$a->actfij_codigo,'Descripción'=>$a->actfij_descripcion,'Marca / modelo'=>$a->actfij_marca.' / '.$a->actfij_modelo,'Serie'=>$a->actfij_serie,'Adquisición'=>$a->actfij_fecha_adquisicion,'Oficina'=>L::table('oficinas')->where('ofi_id',$a->ofi_id)->value('ofi_nombre'),'Área / ambiente'=>$a->actfij_ubicacion_area.' / '.$a->actfij_ubicacion_ambiente,'Custodio'=>L::table('personal')->where('per_id',$a->actfij_cus_id)->value('per_nombres_fill'),'Fecha de asignación'=>$this->date($a->actfij_cus_fecha_asignacion),'Costo del activo (Bs)'=>$a->actfij_costo_activo_ml,'Estado'=>$a->actfij_estado_bien_descripcion,'Conservación'=>$a->actfij_conservacion_descripcion];
  $assignments=DB::table('app_asset_assignments as h')->join('msib.personal as p','p.per_id','=','h.custodian_id')->join('msib.oficinas as o','o.ofi_id','=','h.office_id')->where('h.asset_id',$id)->orderBy('h.created_at')->get(['h.created_at as fecha','p.per_nombres_fill as custodio','o.ofi_nombre as oficina','h.actor as registrado_por','h.notes as motivo'])->map(fn($x)=>(array)$x)->all();$r['sections'][]=$this->section('Historial de custodia',$this->cols(['fecha'=>'Fecha','custodio'=>'Custodio','oficina'=>'Oficina','registrado_por'=>'Registrado por','motivo'=>'Motivo']),$assignments);$r['notes'][]=$a->actfij_observacion;$r['notes'][]='Constancia adaptada de la nueva aplicación. El XPZ contiene entidades de actas, pero no se encontró un procedimiento de impresión de acta final; esta ficha no se presenta como una reproducción de ese formato.';$r['signatures']=[['statement'=>'Recibido por (custodio)','name'=>$r['metadata']['Custodio'],'role'=>'','date'=>'','origin'=>'Custodio registrado'],['statement'=>'Entregado / autorizado por','name'=>'','role'=>'','date'=>'','origin'=>'Firma pendiente']];return $this->finish($r);
 }
